(() => { let questions=[['Welcher Hebelarm spart Kraft?',['Der längere Kraftarm','Der kürzere Kraftarm','Beide gleich'],0],['Wo liegt bei einer Schere der Drehpunkt?',['An der Spitze','An der Schraube','Am Griffende'],1],['Was hilft beim Gleichgewicht am Hebel?',['Ein passender Kraftausgleich','Ein zufälliger Druck','Eine kürzere Wippe'],1],['Welche Masse wirkt stärker?',['Die mit größerer Kraft','Immer die rechte','Immer die linke'],0],['Was passiert bei doppeltem Kraftarm?',['Man braucht doppelte Kraft','Man braucht halbe Kraft','Nichts'],1]];if(location.pathname.includes("mission5"))questions=[["Welche Größe muss bei einer Balkenwaage ausgeglichen werden?",["Nur die Masse","Die Hebelwirkung","Nur die Farbe"],1],["Was passiert mit der nötigen Kraft bei längerem Kraftarm?",["Sie wird größer","Sie bleibt immer gleich","Sie wird kleiner"],2],["6 kg in 30 cm erzeugen welche Wirkung im Vergleich zu 4 kg?",["Keine","Eine kleinere","Eine größere"],2],["Wo muss eine kleinere Masse hängen, um auszugleichen?",["Direkt am Drehpunkt","Näher am Drehpunkt","Weiter vom Drehpunkt entfernt"],2],["Was braucht ein Hebel zum Gleichgewicht?",["Gleiche Längen immer","Ausgeglichene Wirkungen","Gleiche Farben"],1]];else if(location.pathname.includes("mission8"))questions=[["Was spart beim Öffnen einer Kiste Kraft?",["Kein Drehpunkt","Drehpunkt weit weg von der Last","Drehpunkt nah an der Last"],2],["Was verbessert einen Schraubenschlüssel?",["Ein kürzerer Griff","Ein schwererer Name","Ein längerer Griff"],2],["Wo sollte die Last in der Schubkarre liegen?",["Näher an den Griffen","Näher am Rad","Oben auf dem Griff"],1],["Was wird bei längerem Kraftarm kleiner?",["Die Last selbst","Der Drehpunkt","Die benötigte Kraft"],2],["Welche Aussage stimmt?",["Arbeit wird zauberhaft","Kraft kann gespart werden","Kraft verschwindet"],1]];let timer,seconds=30,score=0,index=0,answered=false;const overlay=document.createElement('div');overlay.id='quickRound';overlay.style.cssText='position:fixed;inset:0;z-index:99;background:rgba(100,0,0,.95);color:#fff;padding:24px;display:none;overflow:auto;font-family:system-ui';const blinkStyle=document.createElement('style');blinkStyle.textContent='@keyframes qrBlink{from{background:rgba(80,0,0,.96)}to{background:rgba(255,18,18,.99)}}';document.head.appendChild(blinkStyle);overlay.style.animation='qrBlink .75s ease-in-out infinite alternate';document.body.appendChild(overlay);function start(){seconds=30;score=0;index=0;render();clearInterval(timer);timer=setInterval(()=>{seconds--;document.getElementById('qrTimer').textContent=seconds;if(seconds<=0){clearInterval(timer);finish(false)}},1000);overlay.style.display='block'}function render(){const q=questions[index];overlay.innerHTML='<div style="max-width:760px;margin:auto;text-align:center"><div style="font-size:12px;letter-spacing:.18em">NOTFALL-PROTOKOLL</div><h1 style="font-size:clamp(42px,8vw,84px);margin:8px 0">SCHNELLRATERUNDE</h1><div style="display:inline-block;font-size:42px;font-weight:1000;letter-spacing:.08em;color:#ffffff;background:#5b0000;border:3px solid #ffffff;border-radius:14px;padding:8px 18px;box-shadow:0 0 24px #ff0000">00:<span id="qrTimer">'+String(seconds).padStart(2,'0')+'</span></div><p>Frage '+(index+1)+' von '+questions.length+' · mindestens 3 richtig</p><div style="background:#260606;border:2px solid #ff5e5e;border-radius:18px;padding:24px;margin-top:25px;font-size:22px;font-weight:800">'+q[0]+'</div><div id="qrChoices" style="display:grid;gap:12px;margin-top:18px">'+q[1].map((a,i)=>'<button data-i="'+i+'" style="padding:16px;border:2px solid #ff9a9a;border-radius:12px;background:#540d0d;color:#fff;font-size:17px;cursor:pointer">'+a+'</button>').join('')+'</div><div id="qrScore" style="margin-top:18px">Bisher richtig: '+score+'</div></div>';overlay.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;if(Number(b.dataset.i)===q[2])score++;setTimeout(()=>{answered=false;if(index<questions.length-1){index++;render()}else{clearInterval(timer);finish(score>=3)}},250)})}function finish(passed){overlay.innerHTML='<div style="max-width:760px;margin:12vh auto;text-align:center"><h1 style="font-size:clamp(55px,12vw,130px);margin:0">'+(passed?'GESCHAFFT!':'SCHADE !!!')+'</h1><p style="font-size:24px">'+(passed?'Schnell gedacht und richtig entschieden.':'Du hast '+score+' von 5 Fragen richtig. Versuch es noch einmal!')+'</p><button id="qrRetry" style="padding:16px 28px;border:0;border-radius:99px;background:#fff;color:#8b0000;font-weight:900;font-size:18px;cursor:pointer">'+(passed?'Weiter zur Mission':'Schnellraterunde nochmal starten')+'</button></div>';document.getElementById('qrRetry').onclick=()=>{if(passed){overlay.style.display='none';const n=document.getElementById('next');if(n){n.style.display='inline-block';n.onclick=()=>location.href='index.html#board'}else location.href='index.html#board'}else start()}}window.launchQuickRound=start;window.addEventListener('load',()=>{const c=document.getElementById('check');if(c)c.addEventListener('click',()=>{if(document.getElementById('pinzette')?.value==='einseitig'&&document.getElementById('schere')?.value==='zweiseitig'&&document.getElementById('nussknacker')?.value==='einseitig'&&document.getElementById('angel')?.value==='einseitig')setTimeout(start,250)})})})();
